"""In-memory URL-shortening domain service."""

from __future__ import annotations

import base64
import hashlib
from threading import Lock
from urllib.parse import urlsplit


class URLShortenerError(Exception):
    """Base class for domain-level URL-shortener failures."""


class InvalidURLError(URLShortenerError):
    """Raised when a submitted URL is not an absolute HTTP(S) URL."""


class UnknownShortCodeError(URLShortenerError):
    """Raised when no original URL exists for a short code."""


class URLShortener:
    """Deterministic, collision-safe, process-local URL repository."""

    def __init__(self) -> None:
        self._url_by_code: dict[str, str] = {}
        self._code_by_url: dict[str, str] = {}
        self._lock = Lock()

    def shorten(self, url: str) -> str:
        """Return a stable unique code for one valid absolute HTTP(S) URL."""

        validated = _validate_url(url)
        with self._lock:
            existing = self._code_by_url.get(validated)
            if existing is not None:
                return existing

            nonce = 0
            while True:
                code = _candidate_code(validated, nonce)
                owner = self._url_by_code.get(code)
                if owner is None or owner == validated:
                    self._url_by_code[code] = validated
                    self._code_by_url[validated] = code
                    return code
                nonce += 1

    def resolve(self, code: str) -> str:
        """Return the original URL for a known code."""

        if not isinstance(code, str) or not code:
            raise UnknownShortCodeError("Unknown short code.")
        with self._lock:
            try:
                return self._url_by_code[code]
            except KeyError as error:
                raise UnknownShortCodeError(
                    f"Unknown short code: {code}."
                ) from error


def _validate_url(url: str) -> str:
    if not isinstance(url, str) or not url or url != url.strip():
        raise InvalidURLError("URL must be a non-empty absolute HTTP(S) URL.")
    if any(character.isspace() for character in url):
        raise InvalidURLError("URL must not contain whitespace.")
    try:
        parsed = urlsplit(url)
        port = parsed.port
    except ValueError as error:
        raise InvalidURLError("URL authority is malformed.") from error
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not parsed.netloc
        or parsed.hostname is None
        or (port is not None and not 1 <= port <= 65535)
    ):
        raise InvalidURLError("URL must be an absolute HTTP(S) URL.")
    return url


def _candidate_code(url: str, nonce: int) -> str:
    digest = hashlib.sha256(f"{url}\0{nonce}".encode("utf-8")).digest()
    return base64.urlsafe_b64encode(digest[:6]).decode("ascii").rstrip("=")

"""Thin dependency-free WSGI adapter for the URL-shortener service."""

from __future__ import annotations

import json
import os
from collections.abc import Callable, Iterable
from typing import Any
from urllib.parse import unquote
from wsgiref.simple_server import make_server

from url_shortener.service import InvalidURLError, UnknownShortCodeError, URLShortener

StartResponse = Callable[[str, list[tuple[str, str]]], Any]


class URLShortenerApplication:
    """WSGI application exposing shorten and resolve operations."""

    def __init__(
        self,
        service: URLShortener | None = None,
        *,
        base_url: str = "http://127.0.0.1:8000",
    ) -> None:
        self.service = service or URLShortener()
        self.base_url = base_url.rstrip("/")

    def __call__(
        self, environ: dict[str, Any], start_response: StartResponse
    ) -> Iterable[bytes]:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))
        if path == "/shorten":
            if method == "POST":
                return self._shorten(environ, start_response)
            return _json_response(
                start_response,
                "405 Method Not Allowed",
                {"error": "method_not_allowed"},
            )
        if method == "GET" and path.startswith("/") and path != "/":
            return self._resolve(unquote(path[1:]), start_response)
        return _json_response(
            start_response, "404 Not Found", {"error": "not_found"}
        )

    def _shorten(
        self, environ: dict[str, Any], start_response: StartResponse
    ) -> Iterable[bytes]:
        try:
            length = int(environ.get("CONTENT_LENGTH") or "0")
            if length < 1 or length > 1_000_000:
                raise ValueError
            stream = environ["wsgi.input"]
            payload = json.loads(stream.read(length).decode("utf-8"))
            if not isinstance(payload, dict) or not isinstance(payload.get("url"), str):
                raise ValueError
        except (KeyError, TypeError, ValueError, UnicodeDecodeError, json.JSONDecodeError):
            return _json_response(
                start_response,
                "400 Bad Request",
                {"error": "invalid_request", "message": "Expected JSON with a URL."},
            )
        try:
            code = self.service.shorten(payload["url"])
        except InvalidURLError as error:
            return _json_response(
                start_response,
                "400 Bad Request",
                {"error": "invalid_url", "message": str(error)},
            )
        return _json_response(
            start_response,
            "201 Created",
            {"code": code, "short_url": f"{self.base_url}/{code}"},
        )

    def _resolve(self, code: str, start_response: StartResponse) -> Iterable[bytes]:
        try:
            original_url = self.service.resolve(code)
        except UnknownShortCodeError:
            return _json_response(
                start_response,
                "404 Not Found",
                {"error": "unknown_code", "code": code},
            )
        start_response(
            "302 Found",
            [("Location", original_url), ("Content-Length", "0")],
        )
        return [b""]


def _json_response(
    start_response: StartResponse, status: str, payload: dict[str, object]
) -> list[bytes]:
    body = json.dumps(payload, sort_keys=True).encode("utf-8")
    start_response(
        status,
        [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ],
    )
    return [body]


def main() -> None:
    host = os.environ.get("URL_SHORTENER_HOST", "127.0.0.1")
    port = int(os.environ.get("URL_SHORTENER_PORT", "8000"))
    application = URLShortenerApplication(base_url=f"http://{host}:{port}")
    with make_server(host, port, application) as server:
        print(f"URL shortener listening on http://{host}:{port}")
        server.serve_forever()


if __name__ == "__main__":
    main()

